SELECT ib.ib_income_band_sk AS income_band_id, ib.ib_lower_bound, ib.ib_upper_bound, COUNT(DISTINCT c.c_customer_sk) AS num_customers, AVG(2023 - c.c_birth_year) AS avg_age, approx_percentile(2023 - c.c_birth_year, 0.5) AS median_age, SUM(CASE WHEN hd.hd_buy_potential = 'High' THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS high_buy_potential_ratio, COUNT(DISTINCT split_part(c.c_email_address, '@', 2)) AS distinct_email_domains, RANK() OVER (ORDER BY COUNT(DISTINCT c.c_customer_sk) DESC) AS income_band_rank FROM customer c JOIN household_demographics hd ON c.c_current_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk WHERE c.c_preferred_cust_flag = 'Y' AND c.c_salutation IN ('Mr.', 'Mrs.') AND c.c_last_name IN ('Norman', 'Hill', 'Small', 'Roy', 'Johnston') GROUP BY ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound ORDER BY num_customers DESC LIMIT 10
